(()=>{var a=document.querySelector("#filter-input");if(a!=null){let o=document.querySelectorAll(".activity-feed-item");a.addEventListener("input",()=>{let t=a.value.trim().toLowerCase();o.forEach(e=>{let l=e.getAttribute("data-title")?.toLowerCase()??"",r=e.getAttribute("data-tags")?.toLowerCase()??"",s=e.getAttribute("data-year")?.toLowerCase()??"";l.includes(t)||r.includes(t)||s.includes(t)?(e.style.display="",document.querySelector(`#year-${s}`).style.display=""):(e.style.display="none",document.querySelector(`#year-${s}`).style.display="none")})})}})();
